const V={x:500,y:280,w:620,h:760};let pinLayer=null,pinSpecs=[];
function aspect(){const r=map.getBoundingClientRect();return r.width&&r.height?r.height/r.width:1.3}
function clampV(){const a=aspect();V.w=Math.max(160,Math.min(MW*1.05,V.w));V.h=V.w*a;
  V.x=Math.max(-V.w*.25,Math.min(MW-V.w*.75,V.x));V.y=Math.max(-V.h*.25,Math.min(MH-V.h*.75,V.y));
  map.setAttribute("viewBox",`${V.x} ${V.y} ${V.w} ${V.h}`);drawPins()}
function zoomAt(f,cx,cy){const nw=Math.max(160,Math.min(MW*1.05,V.w/f)),k=nw/V.w;if(cx===undefined){cx=V.x+V.w/2;cy=V.y+V.h/2}
  V.x=cx-(cx-V.x)*k;V.y=cy-(cy-V.y)*k;V.w=nw;clampV()}
function centerOn(cx,cy,w){V.w=w;V.x=cx-w/2;V.y=cy-w*aspect()/2;clampV()}
