function fitDay(){const pts=dayEvents(S.day).filter(e=>e.p).map(e=>PLACES[e.p]);
  if(!pts.length){centerOn(800,540,600);return}
  const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);
  const a=aspect(),w=Math.max(480,x1-x0+220,(y1-y0+380)/a);centerOn((x0+x1)/2,(y0+y1)/2-30,w)}
